import type { SdgnMissionQcm } from "./sdgnMissionQcmBank";

/** Banque officielle du DS SDGN Terminale (100 QCM cas entreprise). */
export const SDGN_DS_TERMINALE_QCM: SdgnMissionQcm[] = [
  { id: "sdgn-t-ds-01", chapter: 1, difficulte: "difficile", question: "(Contexte) L'entreprise \"MobiCity\" fait face à une concurrence féroce sur la vente de vélos. Elle décide de ne plus vendre ses vélos, mais de les louer à la minute via une application mobile.\nProblématique : Quelle mutation stratégique l'entreprise opère-t-elle ?", choix: ["Une innovation de produit, car l'intégration d'une application mobile modifie physiquement les caractéristiques techniques du vélo vendu.", "Une innovation de modèle économique, car l'entreprise bascule vers l'économie de la fonctionnalité en vendant l'usage plutôt que la propriété du bien.", "Une innovation de procédé, car la location permet de réduire les charges fixes liées à la production en usine.", "Une stratégie d'écrémage, car la location à la minute génère un chiffre d'affaires immédiat supérieur à la vente."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-02", chapter: 1, difficulte: "difficile", question: "(Contexte) La start-up \"EcoTech\" a un Fonds de Roulement Net Global (FRNG) de 80 000 €. Son cycle d'exploitation génère un Besoin en Fonds de Roulement (BFR) de 110 000 €.\nProblématique : Quelle est la situation de trésorerie et la décision adaptée ?", choix: ["La Trésorerie Nette est de + 30 000 €, l'entreprise peut donc autofinancer de nouveaux investissements matériels.", "La Trésorerie Nette est de - 30 000 €, l'entreprise doit négocier un concours bancaire courant (découvert) car ses ressources stables ne couvrent pas son besoin d'exploitation.", "La Trésorerie Nette est nulle, l'entreprise doit allonger le délai de paiement accordé à ses clients pour équilibrer son bilan.", "La Trésorerie Nette est de - 30 000 €, l'entreprise doit contracter un emprunt obligataire sur 10 ans pour financer ce déficit d'exploitation."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-03", chapter: 1, difficulte: "difficile", question: "(Contexte) L'usine \"Plastica\" fabrique 10 000 chaises. Le coût complet unitaire est de 15 € (dont 10 € de charges variables et 5 € de charges fixes). L'usine a une capacité maximale de 15 000 chaises. Un client propose d'acheter 3 000 chaises à 12 € l'unité.\nProblématique : Quelle est la décision rationnelle en contrôle de gestion ?", choix: ["Accepter, car le prix de 12 € couvre le coût variable (10 €) et génère une marge positive, les charges fixes étant déjà absorbées par la production actuelle.", "Refuser, car le prix de 12 € est inférieur au coût complet (15 €), ce qui détruit mécaniquement la valeur ajoutée de l'entreprise.", "Accepter, car une vente à 12 € permet de transformer les charges fixes en charges variables directes.", "Refuser, car la marge sur coût spécifique est obligatoirement négative en situation de sous-activité."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-04", chapter: 1, difficulte: "difficile", question: "(Contexte) La banque \"NordFinance\" a supprimé le transfert manuel des dossiers de crédit. Désormais, dès qu'un conseiller valide une étape sur son poste, le dossier apparaît automatiquement sur l'écran du directeur pour validation finale.\nProblématique : Quel outil numérique permet cette optimisation ?", choix: ["Le Big Data, car l'algorithme analyse les traces numériques du client pour accorder le prêt.", "Le Workflow (flux de travaux), car il automatise la circulation de l'information et des tâches entre les acteurs du processus.", "Le Cloud Computing, car il permet de réduire les charges fixes d'amortissement informatique.", "La Blockchain, car elle certifie la signature du directeur sans tiers de confiance."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-05", chapter: 1, difficulte: "difficile", question: "(Contexte) L'enseigne \"ModeFast\" renouvelle ses collections toutes les deux semaines. Les usines ne lancent la production d'un vêtement que lorsque les données de caisse indiquent qu'il se vend bien.\nProblématique : Sur quel modèle logistique cette Supply Chain repose-t-elle ?", choix: ["Une production en flux poussés, car la production anticipe la demande pour constituer des stocks de sécurité.", "Une production en flux tendus (Juste-à-Temps), car elle est déclenchée par la demande réelle, ce qui permet de minimiser le BFR en limitant les stocks.", "Une production à l'unité, car chaque vêtement est personnalisé selon les exigences d'un client spécifique.", "Une production en flux tendus, car l'objectif est de saturer les usines pour réduire le coût fixe unitaire."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-06", chapter: 1, difficulte: "difficile", question: "(Contexte) La PME \"WoodDesign\" refuse de puiser dans sa trésorerie ou d'alourdir son endettement au bilan pour acquérir une nouvelle machine à commande numérique (150 000 €).\nProblématique : Quel mode de financement répond à ces contraintes comptables ?", choix: ["Le crédit-bail (leasing), car l'investissement est remplacé par une charge locative d'exploitation, n'impactant pas les dettes financières affichées au bilan.", "L'autofinancement, car il consiste à utiliser l'épargne salariale sans toucher à la trésorerie de l'entreprise.", "Le découvert bancaire, car il permet d'augmenter le FRNG de manière immédiate et transparente.", "L'augmentation de capital, car elle permet de réduire les emplois stables de l'organisation."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-07", chapter: 1, difficulte: "difficile", question: "(Contexte) Une association d'aide aux devoirs perçoit 20 000 € de subventions municipales et 5 000 € de dons. Elle a dépensé 24 000 € pour l'achat de matériel éducatif.\nProblématique : Comment s'évalue sa création de valeur ?", choix: ["Exclusivement par son utilité sociale, l'association n'ayant pas le droit de dégager un excédent budgétaire.", "Par son Excédent Brut d'Exploitation (EBE), qui s'élève ici à 1 000 €, mesurant sa rentabilité commerciale.", "Par la réalisation d'un équilibre budgétaire (ici un excédent de 1 000 €) combiné à l'accomplissement de sa mission sociale.", "Par le montant total de ses capitaux propres accumulés sur 10 ans."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-t-ds-08", chapter: 1, difficulte: "difficile", question: "(Contexte) L'entreprise \"CaféPremium\" vend ses machines à café à prix coûtant (sans marge), mais facture très cher les capsules brevetées indispensables à leur fonctionnement.\nProblématique : Quel est ce modèle économique ?", choix: ["Le modèle de la plateforme (ou économie collaborative), basé sur la mise en relation entre vendeurs et acheteurs.", "Le modèle Freemium, car la machine est considérée comme une offre de base gratuite.", "Le modèle \"Bait and Hook\" (appât et hameçon), car l'entreprise subventionne le produit principal pour réaliser sa marge sur les consommables captifs.", "Le modèle du Yield Management, car le prix des capsules varie en temps réel selon la demande."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-t-ds-09", chapter: 1, difficulte: "difficile", question: "(Contexte) L'entreprise \"Alpha\" souhaite évaluer si la ligne de produit \"Gamme X\" est rentable. La Gamme X génère une Marge sur Coûts Variables de 40 000 €. Les machines dédiées exclusivement à la Gamme X coûtent 50 000 € par an en amortissement. Les charges du siège social sont de 100 000 €.\nProblématique : Quelle est la décision rationnelle ?", choix: ["Conserver la Gamme X, car sa marge sur coûts variables est positive, ce qui contribue à payer les charges du siège social.", "Abandonner la Gamme X, car sa marge sur coûts spécifiques est de - 10 000 € : elle ne couvre même pas ses propres charges fixes directes.", "Conserver la Gamme X, car le calcul des coûts complets démontre une rentabilité financière optimisée.", "Abandonner la Gamme X, car l'amortissement des machines est une charge variable qui détruit la valeur ajoutée."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-10", chapter: 1, difficulte: "difficile", question: "(Contexte) Michelin a décidé d'implanter un nouveau centre mondial de R&D au cœur du parc technologique \"Cataroux\", à proximité d'universités, de laboratoires publics et de start-ups.\nProblématique : Quel avantage stratégique l'entreprise recherche-t-elle ?", choix: ["La standardisation des qualifications des ingénieurs concurrents.", "Les externalités de réseau d'un pôle de compétitivité (cluster), favorisant les synergies d'innovation et le partage de compétences sur un territoire.", "La mise en place d'une gouvernance basée sur la démocratie participative locale.", "L'exploitation du modèle économique Freemium pour ses brevets."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-11", chapter: 1, difficulte: "difficile", question: "(Contexte) Un éditeur de logiciels B2B vendait son programme via un CD-Rom payable une seule fois. Il propose désormais son logiciel via un accès web, facturé 50 € par mois par utilisateur.\nProblématique : Quelle mutation opère cet éditeur (SaaS) ?", choix: ["Une innovation de modèle économique, car il passe d'une logique de vente de produit (licence) à une facturation récurrente liée à l'usage (abonnement).", "Une innovation de procédé, car le CD-Rom est remplacé par un téléchargement direct.", "Une démarche de RSE, car la suppression du CD-Rom limite la production de déchets plastiques.", "Une stratégie d'écrémage, car le coût total sur 10 ans sera inférieur à l'achat initial."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-12", chapter: 1, difficulte: "difficile", question: "(Contexte) Pour financer une nouvelle ligne de production, la direction hésite entre l'autofinancement et un emprunt bancaire à 3%. La rentabilité économique du projet est estimée à 8%.\nProblématique : Quelle décision d'endettement doit être prise et pourquoi ?", choix: ["Refuser l'emprunt, car tout endettement dégrade obligatoirement l'indépendance financière et la liquidité de l'entreprise.", "Accepter l'emprunt, car l'effet de levier financier est positif : la rentabilité économique (8%) étant supérieure au coût de la dette (3%), l'endettement améliorera la rentabilité des capitaux propres.", "Refuser l'emprunt, car cela entraînerait un effet de massue réduisant la Marge sur Coût Spécifique.", "Accepter l'emprunt, car les charges d'intérêts bancaires se transforment en Valeur Ajoutée."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-13", chapter: 1, difficulte: "difficile", question: "(Contexte) Un supermarché allonge le délai de paiement de ses fournisseurs (de 45 à 60 jours) tout en maintenant un encaissement au comptant de ses clients.\nProblématique : Quel est l'impact financier de cette pratique sur son cycle d'exploitation ?", choix: ["Une augmentation de la Trésorerie Nette, car cette pratique dégage une ressource de financement (BFR négatif) qui alimente directement les liquidités.", "Une diminution du FRNG, car les dettes fournisseurs font partie intégrante des emplois stables.", "Une augmentation du BFR, car le décalage de trésorerie s'accentue en défaveur du supermarché.", "Une baisse du chiffre d'affaires, car les fournisseurs répercuteront ce délai sur leurs prix de vente."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-14", chapter: 1, difficulte: "difficile", question: "(Contexte) L'entreprise de menuiserie \"BoisEco\" a vu sa production chuter de 20% cette année suite à la perte d'un contrat public. Elle n'a licencié personne et a gardé toutes ses machines.\nProblématique : Quel est l'impact mécanique sur la structure de ses coûts unitaires ?", choix: ["Une baisse du coût variable unitaire, grâce aux économies d'échelle réalisées sur l'achat du bois.", "Une augmentation du coût fixe unitaire, car les charges de structure (loyers, salaires fixes) se répartissent sur un plus petit nombre de produits finis.", "Une diminution des charges fixes totales, l'entreprise adaptant naturellement sa structure à la sous-activité.", "Une stabilité absolue du coût complet unitaire, le seuil de rentabilité n'étant pas modifié."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-15", chapter: 2, difficulte: "difficile", question: "(Contexte) Face à la concurrence des banques en ligne, une agence bancaire traditionnelle exige de ses conseillers qu'ils réduisent le temps d'entretien par client tout en augmentant la vente de produits financiers complexes.\nProblématique : Quel risque social cette double injonction paradoxale génère-t-elle ?", choix: ["Une amélioration de la dynamique de groupe grâce à la supervision directe.", "L'émergence de Risques Psychosociaux (RPS), la perte de sens et le stress dégradant la Qualité de Vie au Travail et la performance.", "Une augmentation mécanique de la participation et de l'intéressement.", "Une baisse du turn-over, les salariés étant stimulés par le défi."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-16", chapter: 2, difficulte: "difficile", question: "(Contexte) Dans le studio de création de jeux vidéo \"GameArt\", une équipe de 10 développeurs et designers doit créer un nouveau niveau de jeu. Aucune règle n'est fixée, l'équipe discute continuellement via une messagerie interne pour surmonter les bugs techniques imprévus.\nProblématique : Quel mécanisme de coordination est à l'œuvre ?", choix: ["La standardisation des procédés, car ils utilisent tous le même logiciel de messagerie.", "L'ajustement mutuel, car la communication informelle en temps réel est le seul moyen de coordonner une tâche complexe et incertaine.", "La supervision directe, car le directeur du studio surveille discrètement les conversations sur la messagerie.", "La standardisation des résultats, car l'objectif final est la création d'un niveau de jeu fonctionnel."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-17", chapter: 2, difficulte: "difficile", question: "(Contexte) La multinationale \"LogisCorp\" laisse ses filiales étrangères totalement libres de concevoir leurs propres campagnes publicitaires et de choisir leurs fournisseurs locaux, à condition de remonter les chiffres de rentabilité chaque mois au siège.\nProblématique : Comment qualifier cette organisation du pouvoir ?", choix: ["Une centralisation stricte, car le siège parisien contrôle les résultats financiers mensuels.", "Une décentralisation du pouvoir, favorisant la réactivité locale par la délégation, encadrée par un reporting (contrôle a posteriori).", "Un style de direction autoritaire exploiteur, car les filiales subissent la pression du chiffre.", "Une démarche d'ajustement mutuel international."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-18", chapter: 2, difficulte: "difficile", question: "(Contexte) Dans un service client, le taux de rotation (turn-over) est passé de 5% à 35% en deux ans. La direction RH cherche à endiguer cette hémorragie.\nProblématique : Quelle conclusion managériale tirer de cet indicateur du bilan social ?", choix: ["L'indicateur est positif, car un turn-over élevé réduit mécaniquement la masse salariale et augmente l'Excédent Brut d'Exploitation.", "L'indicateur révèle un dysfonctionnement social profond (mauvaises conditions de travail, faible rémunération) générant des coûts cachés majeurs de recrutement et de formation.", "L'indicateur traduit la réussite de la stratégie de GPEC, l'entreprise se séparant des profils obsolètes.", "L'indicateur prouve que l'entreprise a adopté un leadership de type transformationnel."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-19", chapter: 2, difficulte: "difficile", question: "(Contexte) Les salariés d'une usine automobile se mettent en grève pour dénoncer le chronométrage excessif de leurs gestes sur la chaîne de montage (taylorisme). La direction propose de transformer leurs postes : ils assembleront désormais un moteur entier et géreront eux-mêmes le contrôle qualité.\nProblématique : Quelle solution organisationnelle est appliquée ?", choix: ["L'élargissement des tâches, car les salariés font simplement plus de tâches répétitives.", "L'enrichissement des tâches, car l'entreprise augmente la complexité, l'autonomie et les responsabilités des opérateurs, redonnant du sens au travail.", "La standardisation des qualifications, car les ouvriers devront repasser un diplôme technique.", "Le social washing, car la grève a forcé la direction à agir sous la contrainte."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-20", chapter: 2, difficulte: "difficile", question: "(Contexte) Pour attirer les jeunes développeurs, la société \"WebDev\" sponsorise des événements de e-sport, publie des vidéos sur son cadre de travail \"fun\" et met en avant sa politique d'égalité salariale.\nProblématique : Quel concept RH l'entreprise développe-t-elle ?", choix: ["L'e-réputation commerciale, visant à rassurer les clients sur la qualité du code produit.", "La Marque Employeur, utilisant les techniques du marketing pour attirer les candidats cibles et fidéliser les collaborateurs internes par une image positive.", "Le mécénat environnemental, car le e-sport est une discipline immatérielle non polluante.", "L'ajustement mutuel prévisionnel."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-21", chapter: 2, difficulte: "difficile", question: "(Contexte) Un conflit éclate entre les acheteurs (qui veulent commander en gros pour réduire les prix) et les logisticiens (qui n'ont plus de place dans l'entrepôt). Le directeur impose une règle stricte : commandes limitées à 50 palettes maximum, sans écouter les arguments des acheteurs.\nProblématique : Quel mode de résolution des conflits est utilisé ?", choix: ["Le recours hiérarchique, car la décision est prise de manière unilatérale par l'autorité supérieure pour stopper net le conflit.", "Le dépassement par la négociation, car une règle claire a été trouvée pour satisfaire l'entrepôt.", "L'évitement, car le directeur refuse d'écouter les acheteurs.", "L'ajustement mutuel, car les logisticiens se sont adaptés aux acheteurs."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-22", chapter: 2, difficulte: "difficile", question: "(Contexte) Selon la théorie des facteurs de motivation de Herzberg, la direction d'une entreprise s'étonne que l'augmentation de la prime de Noël n'ait motivé les équipes que pendant quelques semaines.\nProblématique : Comment la théorie bi-factorielle explique-t-elle ce phénomène ?", choix: ["La rémunération est un \"facteur moteur\" dont l'effet s'estompe si elle n'est pas versée mensuellement.", "La rémunération est un \"facteur d'hygiène\" : son absence crée de l'insatisfaction (grogne), mais son augmentation ne génère pas de véritable motivation durable, celle-ci provenant de l'intérêt intrinsèque du travail.", "La rémunération répond au besoin d'accomplissement de Maslow, qui est par nature temporaire.", "La rémunération crée un mécanisme de supervision directe oppressant pour le salarié."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-23", chapter: 2, difficulte: "difficile", question: "(Contexte) Dans une concession automobile, le directeur exige que les vendeurs utilisent un script strict pour accueillir le client (exactement les mêmes mots) et qu'ils remplissent un formulaire identique pour chaque vente.\nProblématique : Quel mécanisme de coordination selon Mintzberg est utilisé ?", choix: ["La standardisation des procédés de travail, car le contenu et la séquence des tâches sont spécifiés précisément à l'avance pour garantir l'uniformité du service.", "La standardisation des résultats, car l'objectif final est de réaliser la vente.", "La supervision directe, car le directeur contrôle le chiffre d'affaires en fin de mois.", "L'ajustement mutuel, car le vendeur doit s'adapter aux réponses du client."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-24", chapter: 2, difficulte: "difficile", question: "(Contexte) L'entreprise intègre dans son calcul de performance non seulement l'EBE, mais aussi le nombre de jours de formation dispensés, le taux de recyclage de ses déchets et la baisse des accidents du travail.\nProblématique : Quelle approche de la performance l'entreprise adopte-t-elle ?", choix: ["L'approche de la performance économique classique (Shareholder value).", "L'approche de la performance globale et multidimensionnelle, intégrant les critères économiques, sociaux et environnementaux (RSE).", "L'approche par le Bilan Fonctionnel.", "L'approche de l'économie de la fonctionnalité."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-25", chapter: 2, difficulte: "difficile", question: "(Contexte) Le \"Plan de développement des compétences\" (anciennement plan de formation) de l'entreprise \"IndusPro\" prévoit de former 100 ouvriers à la robotique avancée.\nProblématique : Quel est l'enjeu principal de ce plan pour l'employeur et le salarié ?", choix: ["Maintenir l'employabilité des salariés face à l'évolution technologique et adapter les ressources de l'entreprise pour préserver sa compétitivité.", "Accroître artificiellement les charges de personnel pour diminuer l'impôt sur les sociétés.", "Contourner l'obligation légale de négociation collective avec les syndicats.", "Favoriser le mécanisme d'évitement des conflits interpersonnels."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-26", chapter: 2, difficulte: "difficile", question: "(Contexte) Une entreprise de distribution de colis \"ubérisée\" ne recrute aucun salarié. Elle s'appuie exclusivement sur des milliers de livreurs ayant le statut de micro-entrepreneurs.\nProblématique : Quel enjeu juridique et sociétal cette pratique soulève-t-elle ?", choix: ["La légalité du modèle Freemium appliqué au transport de marchandises.", "La requalification potentielle en contrat de travail si un lien de subordination est prouvé, soulevant la question de la précarité et de la protection sociale des travailleurs de plateformes.", "Le non-respect de l'obligation de publier l'algorithme en Open Data.", "La violation systématique de la standardisation des qualifications."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-27", chapter: 2, difficulte: "difficile", question: "(Contexte) Le constructeur automobile \"AutoPlus\" publie un spot télévisé vantant l'élégance de son nouveau modèle, tout en diffusant le même jour un rapport financier sur sa rentabilité record, et une note interne rassurant ses salariés sur l'emploi.\nProblématique : Quelle stratégie de communication est mise en œuvre ?", choix: ["Une communication de crise ciblée sur l'e-réputation.", "Une communication globale et intégrée, veillant à la cohérence des messages entre les cibles commerciales, institutionnelles et internes.", "Une stratégie d'éthique des affaires imposée par le RGPD.", "Une démarche stricte de Greenwashing financier."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-28", chapter: 2, difficulte: "difficile", question: "(Contexte) La SNCF doit faire face à une grève nationale de ses contrôleurs. La direction et les syndicats représentatifs se réunissent pour trouver un accord sur les primes de fin d'année.\nProblématique : Dans quel cadre institutionnel s'inscrivent ces échanges ?", choix: ["Le mécanisme de l'ajustement mutuel informel.", "Le cadre du dialogue social et de la négociation collective, visant à réguler les relations professionnelles et pacifier le climat social.", "Le principe de la démocratie participative ouverte aux voyageurs.", "La procédure du lanceur d'alerte."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-29", chapter: 2, difficulte: "difficile", question: "(Contexte) L'entreprise déploie un réseau social d'entreprise (RSE) de type \"Yammer\". La direction constate avec satisfaction que des ingénieurs de Lyon et des commerciaux de Strasbourg échangent spontanément des conseils sur une nouvelle technologie, sans passer par leur hiérarchie.\nProblématique : Quel avantage managérial le RSE procure-t-il ici ?", choix: ["L'automatisation du contrôle hiérarchique par le flicage numérique.", "La destruction des silos fonctionnels, favorisant les flux d'informations horizontaux, le travail collaboratif et l'émergence de communautés de pratiques.", "La suppression du besoin de financement lié au BFR.", "La centralisation extrême du pouvoir de décision."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-30", chapter: 3, difficulte: "difficile", question: "(Contexte) Lors d'une réunion de l'équipe de direction, un membre influent parvient systématiquement à rallier les autres à ses idées, bien qu'il ne soit pas le directeur général en titre.\nProblématique : Quel concept illustre cette situation ?", choix: ["Le pouvoir légal institutionnel (Autorité).", "Le leadership, c'est-à-dire la capacité d'influence informelle, d'entraînement et de persuasion reconnue par le groupe.", "La standardisation des résultats décisionnels.", "Le style de direction autoritaire exploiteur."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-31", chapter: 3, difficulte: "difficile", question: "(Contexte) La start-up \"DataDrive\" analyse les clics, le temps passé sur chaque page et les recherches de ses visiteurs. Elle utilise ces informations pour modifier l'ergonomie de son site en temps réel.\nProblématique : Comment s'appelle l'exploitation de ces éléments immatériels ?", choix: ["L'exploitation des données ouvertes (Open Data) gouvernementales.", "L'exploitation des traces numériques (Big Data), transformées en ressources stratégiques pour personnaliser l'offre et optimiser l'expérience client.", "Le piratage illégal des systèmes d'information concurrents.", "La mise en œuvre d'une architecture Pair-à-Pair (P2P)."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-32", chapter: 3, difficulte: "difficile", question: "(Contexte) Une compagnie d'assurance utilise une Intelligence Artificielle pour analyser les sinistres. L'IA refuse systématiquement d'indemniser les habitants d'un certain quartier défavorisé, car elle a appris sur la base de données historiques intégrant ce paramètre géographique.\nProblématique : Quel est le problème éthique soulevé par cette IA ?", choix: ["L'IA applique une stratégie d'écrémage tarifaire illégale.", "L'IA reproduit un biais algorithmique (ou biais d'apprentissage), automatisant une discrimination systémique opaque.", "L'IA viole le principe d'interopérabilité des bases de données relationnelles.", "L'IA respecte la théorie des parties prenantes au détriment des actionnaires."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-33", chapter: 3, difficulte: "difficile", question: "(Contexte) Le ministère de la Santé met librement à disposition sur une plateforme web les données anonymisées concernant la localisation et l'équipement de tous les hôpitaux de France, afin que des développeurs créent des applications d'urgence.\nProblématique : Quelle politique publique est appliquée ?", choix: ["Le Cloud Computing d'État.", "L'Open Data (données ouvertes), visant la transparence et la stimulation de l'innovation externe créatrice de services à valeur ajoutée.", "La Blockchain sanitaire, garantissant l'inviolabilité des données.", "Le Crowdfunding citoyen."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-34", chapter: 3, difficulte: "difficile", question: "(Contexte) Un e-commerçant stockait toutes les données de ses clients européens sur ses propres serveurs dans sa cave. Pour plus de sécurité et de flexibilité, il confie cet hébergement à Microsoft Azure (Cloud Computing).\nProblématique : Quel risque managérial et juridique accompagne cette décision ?", choix: ["L'augmentation mécanique des charges fixes liées à l'amortissement du matériel.", "Le risque de dépendance stratégique envers le prestataire et les interrogations sur la souveraineté territoriale des données (RGPD) stockées sur des serveurs étrangers.", "La disparition automatique des clés primaires dans la base de données relationnelle.", "La suppression de la fonction SI (Système d'Information) dans l'entreprise."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-35", chapter: 3, difficulte: "difficile", question: "(Contexte) L'entreprise \"Laiterie de l'Ouest\" subit une attaque par \"Ransomware\" cryptant l'intégralité de sa comptabilité. Le pirate exige 100 000 € pour débloquer les fichiers.\nProblématique : Quel pilier de la cybersécurité a été rompu ?", choix: ["La traçabilité, l'entreprise ne sachant pas qui a saisi les dernières écritures.", "La disponibilité et l'intégrité de l'information, les données étant inaccessibles et illisibles pour l'organisation.", "L'interopérabilité, le logiciel comptable refusant de communiquer avec les banques.", "La transparence des algorithmes imposée par le régulateur."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-36", chapter: 3, difficulte: "difficile", question: "(Contexte) Une marque de prêt-à-porter affirme dans ses publicités que ses t-shirts sont \"100% verts pour la planète\", car ils contiennent 1% de coton bio, alors que 99% du vêtement est en polyester fabriqué dans des usines polluantes en Asie.\nProblématique : Comment qualifier cette pratique de communication ?", choix: ["Un mécénat environnemental exemplaire.", "Du Greenwashing (éco-blanchiment), une pratique éthiquement condamnable visant à donner une image faussement éco-responsable déconnectée de la réalité industrielle.", "Une application stricte des principes de l'économie circulaire.", "Une innovation de commercialisation de type phygitale."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-37", chapter: 3, difficulte: "difficile", question: "(Contexte) La start-up \"FairPhone\" intègre dès la conception de son téléphone la possibilité de démonter et changer facilement l'écran ou la batterie, limitant ainsi les déchets électroniques.\nProblématique : Dans quel concept global de gestion s'inscrit cette démarche ?", choix: ["L'obsolescence programmée stratégique.", "L'éco-conception au sein de l'économie circulaire, allongeant le cycle de vie du produit (PLM) et réduisant son empreinte environnementale globale.", "L'ajustement mutuel technique.", "La standardisation purement esthétique."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-38", chapter: 3, difficulte: "difficile", question: "(Contexte) Face aux scandales sanitaires ou écologiques, la \"Loi Sapin 2\" impose aux grandes entreprises françaises de mettre en place des procédures pour recueillir les signalements des salariés témoins de délits dans leur entreprise.\nProblématique : Quel dispositif juridique protège ces salariés ?", choix: ["Le statut de \"Lanceur d'alerte\", garantissant la confidentialité et la protection contre le licenciement ou les sanctions hiérarchiques.", "La clause de non-concurrence, interdisant au salarié de dénoncer son employeur à un concurrent.", "L'interdiction formelle de recourir aux réseaux sociaux (Shadow IT).", "Le principe du contradictoire en Open Data."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-39", chapter: 3, difficulte: "difficile", question: "(Contexte) Une multinationale de l'agroalimentaire collabore avec des ONG environnementales pour certifier la provenance durable de son huile de palme, modifiant ainsi sa chaîne d'approvisionnement.\nProblématique : Quelle théorie du management justifie cette décision d'intégrer des acteurs externes ?", choix: ["La théorie de la valeur actionnariale, maximisant les dividendes à court terme.", "La théorie des \"Parties Prenantes\", postulant que la performance et la survie de l'organisation dépendent de sa capacité à prendre en compte les attentes des acteurs de son écosystème (ONG, fournisseurs, société civile).", "La théorie X de l'organisation scientifique du travail.", "La standardisation des qualifications des agriculteurs locaux."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-40", chapter: 3, difficulte: "difficile", question: "(Contexte) Un supermarché français remplace toutes ses étiquettes de prix papier par des écrans électroniques mis à jour en temps réel par ondes radio depuis le siège central.\nProblématique : Quel est l'impact de ce choix technologique (SI) sur le processus de gestion commerciale ?", choix: ["La décentralisation du pouvoir de décision vers les chefs de rayon.", "L'automatisation du processus d'étiquetage, fiabilisant l'information (suppression des erreurs de prix en caisse) et augmentant la productivité en supprimant une tâche manuelle répétitive.", "La transformation du modèle économique vers la gratuité (Freemium).", "Le passage à une stratégie de distribution en canal court (désintermédiation)."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-41", chapter: 3, difficulte: "difficile", question: "(Contexte) \"Vinted\", plateforme de revente de vêtements entre particuliers (C2C), prélève une \"commission de protection acheteur\" sur chaque transaction. Elle n'achète ni ne vend aucun vêtement elle-même.\nProblématique : Sur quel modèle la création de valeur de Vinted repose-t-elle ?", choix: ["L'intégration verticale pure, contrôlant la chaîne logistique de bout en bout.", "L'intermédiation numérique de plateforme, monétisant la confiance et la mise en relation d'une communauté au sein de l'économie collaborative.", "La production en flux poussés de biens immatériels.", "L'ubérisation stricte du salariat logistique."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-42", chapter: 3, difficulte: "difficile", question: "(Contexte) Afin de sécuriser la traçabilité de ses diamants contre le commerce illégal (\"diamants de sang\"), le joaillier \"De Beers\" inscrit chaque pierre dans un registre numérique distribué et partagé par tous les acteurs de la filière.\nProblématique : Quelle technologie garantit l'inviolabilité de ce registre ?", choix: ["Le Cloud Computing hybride.", "La Blockchain (Chaîne de blocs), car les transactions sont validées par le réseau et cryptées de manière indélébile sans autorité centrale.", "Le Crowdsourcing collaboratif.", "L'Open Data gouvernemental."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-43", chapter: 3, difficulte: "difficile", question: "(Contexte) Les entreprises du groupe \"LVMH\" (Dior, Louis Vuitton...) partagent un code de conduite commun exigeant le respect des droits humains fondamentaux par tous leurs sous-traitants dans le monde.\nProblématique : Ce document de régulation interne illustre :", choix: ["L'éthique dans les affaires, formalisant les valeurs de l'organisation pour encadrer les pratiques managériales et commerciales à l'échelle mondiale.", "Une stratégie de prix d'écrémage sur le marché du luxe.", "L'ajustement mutuel des fournisseurs internationaux.", "La mise en conformité stricte avec le budget participatif local."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-44", chapter: 3, difficulte: "difficile", question: "(Contexte) \"LeBonCoin\" et les \"AMAP\" (Associations pour le maintien d'une agriculture paysanne) connaissent un essor foudroyant depuis les années 2010.\nProblématique : Quel changement de fond des modes de consommation justifie ce succès ?", choix: ["La recherche d'une consommation hyper-mondialisée et standardisée.", "La montée de l'anti-consumérisme, de la recherche de sens (circuit court, local) et de l'économie de seconde main, modifiant les rapports d'échange classiques.", "Le rejet définitif de l'outil numérique par les jeunes générations.", "La volonté d'allonger la chaîne logistique pour réduire les coûts fixes."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-45", chapter: 3, difficulte: "difficile", question: "(Contexte) Le ministère de l'Intérieur lance un site permettant aux citoyens de payer leurs amendes routières directement en ligne, 24h/24.\nProblématique : Quel est l'intérêt de cette démarche d'administration électronique ?", choix: ["Augmenter la Marge sur Coût Variable de la police nationale.", "Simplifier le processus pour l'usager tout en améliorant l'efficience de l'organisation publique (réduction des coûts de traitement et du nombre de fonctionnaires assignés à cette tâche).", "Privatiser le service public du recouvrement via une plateforme Freemium.", "Mettre en place un mécanisme de supervision directe des conducteurs."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-46", chapter: 3, difficulte: "difficile", question: "(Contexte) Dans une base de données d'une entreprise (modèle relationnel), la table \"CLIENTS\" possède une colonne \"Numéro_Client\", qui ne peut contenir ni doublon, ni case vide.\nProblématique : Quel est le rôle conceptuel de cette colonne ?", choix: ["C'est une clé étrangère, servant à relier la base de données au système informatique de la banque.", "C'est la clé primaire de la table, indispensable pour identifier de manière absolument unique chaque enregistrement (chaque client) sans confusion possible.", "C'est un algorithme prédictif de fidélisation (Big Data).", "C'est un Smart Contract validant les ventes."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-47", chapter: 3, difficulte: "difficile", question: "(Contexte) La DRH de \"ConstrucPro\" constate une hausse des démissions chez les jeunes embauchés, qui reprochent la rigidité des horaires et le manque de sens de leurs tâches.\nProblématique : Quelle action prioritaire la direction doit-elle mener ?", choix: ["Imposer la lecture du règlement intérieur à chaque pause.", "Repenser la Qualité de Vie au Travail (QVT) et l'aménagement du travail (horaires flexibles, enrichissement des tâches) pour réduire les coûts cachés du turn-over.", "Augmenter le FRNG par une levée de fonds.", "Externaliser la totalité des recrutements."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-48", chapter: 3, difficulte: "difficile", question: "(Contexte) La start-up \"DeliverHome\" confie le design de son nouveau logo à une plateforme en ligne où des milliers de graphistes amateurs proposent leurs idées. Elle ne rémunérera que le projet retenu.\nProblématique : Comment s'appelle cette méthode de création de valeur ?", choix: ["Le Crowdfunding.", "Le Crowdsourcing (externalisation vers la foule), exploitant la créativité de la multitude à très faible coût.", "La standardisation des qualifications des designers.", "L'ajustement mutuel externe."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-49", chapter: 3, difficulte: "difficile", question: "(Contexte) Un laboratoire pharmaceutique finance la recherche contre les maladies rares au sein des hôpitaux publics français, sans aucune contrepartie d'affichage de sa marque sur les bâtiments.\nProblématique : Cette action caritative relève du :", choix: ["Mécénat, constituant un soutien désintéressé d'intérêt général qui renforce discrètement l'identité sociétale de l'entreprise.", "Sponsoring (Parrainage), cherchant un retour sur investissement publicitaire direct.", "Lobbying agressif visant à modifier la législation sanitaire.", "Mécanisme d'ajustement mutuel public-privé."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-50", chapter: 4, difficulte: "difficile", question: "(Contexte) Un manager de centre d'appels interdit à ses employés de parler entre eux. Il écoute toutes les conversations téléphoniques en direct et distribue des blâmes à la moindre erreur de script.\nProblématique : Quelle combinaison théorique décrit parfaitement ce système ?", choix: ["Un style de direction participatif couplé à une coordination par ajustement mutuel.", "Un style de direction autoritaire (Likert) couplé à une coordination par supervision directe stricte et standardisation des procédés (Mintzberg).", "Un leadership transformationnel couplé à l'enrichissement des tâches.", "Une démarche RSE axée sur la standardisation des résultats."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-51", chapter: 4, difficulte: "difficile", question: "(Contexte) La start-up \"FinTechPro\" voit son chiffre d'affaires doubler. Cependant, ses clients paient à 60 jours alors qu'elle doit payer ses serveurs au comptant. Son FRNG est de 20 000 € et son BFR atteint 60 000 €.\nProblématique : Quelle est la conséquence financière de cette croissance ?", choix: ["Une Trésorerie Nette négative (- 40 000 €), car le BFR excède le FRNG, nécessitant un financement à court terme.", "Une Trésorerie Nette négative (- 40 000 €), car le FRNG est trop élevé par rapport aux dettes fournisseurs.", "Une Trésorerie Nette négative (- 40 000 €), car l'entreprise a investi dans des immobilisations incorporelles.", "Une marge sur coût variable négative, car les clients paient trop tard."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-52", chapter: 4, difficulte: "difficile", question: "(Contexte) Le constructeur automobile \"ElectroCar\" s'installe dans la \"Battery Valley\" du Nord de la France, à côté de trois fabricants de batteries, de centres de recherche et d'écoles d'ingénieurs.\nProblématique : Quel avantage stratégique l'entreprise vise-t-elle ?", choix: ["L'exploitation des externalités de réseau d'un pôle de compétitivité (cluster), car la proximité des acteurs crée des synergies d'innovation et un bassin d'emplois qualifiés.", "L'exploitation des externalités de réseau d'un pôle de compétitivité, car l'État garantit l'achat de tous les véhicules produits dans cette zone.", "L'exploitation des externalités d'un pôle de compétitivité, car cela permet de contourner les règles du droit du travail.", "La mise en place d'une structure fonctionnelle centralisée au niveau national."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-53", chapter: 4, difficulte: "difficile", question: "(Contexte) Pour éviter de saturer ses propres ordinateurs, l'agence de communication \"PubliWeb\" loue de l'espace de stockage et des logiciels de montage directement sur les serveurs distants d'Adobe (SaaS).\nProblématique : Quel modèle technologique est utilisé et quel en est l'impact ?", choix: ["L'informatique en nuage (Cloud Computing), car elle transforme un lourd investissement matériel (charges fixes) en facturation à l'usage (charges variables), offrant une grande flexibilité.", "L'informatique en nuage, car elle garantit juridiquement que les données échappent au RGPD européen.", "L'informatique en nuage, car elle centralise les serveurs dans les propres locaux de l'agence pour plus de sécurité.", "La Blockchain, car elle crypte les vidéos de manière décentralisée."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-54", chapter: 4, difficulte: "difficile", question: "(Contexte) Une marque de cosmétiques affirme dans une vaste campagne publicitaire que ses crèmes \"sauvent les océans\" parce qu'elle a réduit l'emballage de 2%, alors que les composants restent hautement toxiques pour la faune marine.\nProblématique : Comment qualifier cette communication ?", choix: ["De Greenwashing (éco-blanchiment), car elle crée une image écoresponsable trompeuse, disproportionnée par rapport à la réalité de ses pratiques.", "De Greenwashing, car l'entreprise refuse de payer ses impôts liés à la pollution.", "De Greenwashing, car elle applique strictement les principes de l'économie circulaire.", "D'une véritable démarche RSE validée par la théorie des parties prenantes."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-55", chapter: 4, difficulte: "difficile", question: "(Contexte) L'administration fiscale utilise un logiciel d'intelligence artificielle pour cibler les entreprises à contrôler. Un chef d'entreprise demande à savoir pourquoi sa société a été ciblée.\nProblématique : Quelle est l'obligation de l'administration ?", choix: ["Respecter la transparence des algorithmes, car la loi oblige l'administration à communiquer les critères ayant conduit le système à prendre cette décision individuelle.", "Respecter la transparence des algorithmes, car le code source complet doit être validé par un vote citoyen en démocratie participative.", "Respecter la transparence des algorithmes, car l'administration doit revendre ces données en Open Data.", "Protéger le secret industriel en refusant de répondre au nom de la cybersécurité."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-56", chapter: 4, difficulte: "difficile", question: "(Contexte) Dans une clinique, le logiciel des urgences est incapable d'envoyer le dossier d'un patient au logiciel du service de radiologie. Les infirmières doivent tout retaper à la main.\nProblématique : Quel concept de système d'information fait ici défaut ?", choix: ["L'interopérabilité, car les différents systèmes informatiques sont incapables de communiquer et d'échanger des données de manière fluide.", "L'interopérabilité, car le réseau fonctionne en Pair-à-Pair (P2P) au lieu d'être centralisé.", "L'interopérabilité, car la clinique subit une cyberattaque par ransomware.", "La méthode des coûts spécifiques, car la double saisie augmente les charges fixes."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-57", chapter: 4, difficulte: "difficile", question: "(Contexte) Le ministère de l'Écologie publie gratuitement en ligne les relevés quotidiens de la qualité de l'air de toutes les villes de France. Une start-up utilise ces fichiers pour créer une application pour les asthmatiques.\nProblématique : Quelle démarche publique favorise cette innovation ?", choix: ["L'Open Data (Données ouvertes), car la mise à disposition libre de données brutes publiques permet à des tiers de créer de nouveaux services à valeur ajoutée.", "L'Open Data, car l'État vend ses informations au plus offrant pour combler son déficit budgétaire.", "L'Open Data, car cela permet de surveiller les déplacements des citoyens malades.", "Le Crowdsourcing, car l'État délègue la mesure de la pollution aux citoyens."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-58", chapter: 4, difficulte: "difficile", question: "(Contexte) La start-up \"AgriTrace\" assure aux consommateurs que le blé de ses pâtes est 100% bio. Chaque étape (récolte, transport, usine) est validée dans un registre numérique distribué, infalsifiable et sans organe de contrôle central.\nProblématique : Quelle technologie sécurise ce processus ?", choix: ["La Blockchain (Chaîne de blocs), car elle permet de certifier et tracer des transactions de manière décentralisée, instaurant la confiance face à l'asymétrie d'information.", "La Blockchain, car elle centralise toutes les preuves sur le serveur unique du ministère de l'Agriculture.", "La Blockchain, car elle supprime les traces numériques pour respecter le principe de minimisation du RGPD.", "Un Progiciel de Gestion Intégré (PGI), car il unifie la comptabilité des agriculteurs."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-59", chapter: 4, difficulte: "difficile", question: "(Contexte) \"DriveMe\", une plateforme de VTC, subit un piratage massif. Les numéros de cartes bancaires et adresses de deux millions de clients sont publiés sur internet.\nProblématique : Quel pilier de la cybersécurité a été rompu ?", choix: ["La confidentialité, car des données sensibles ont été divulguées à des personnes non autorisées.", "La confidentialité, car le système est devenu indisponible (panne) suite à l'attaque.", "La confidentialité, car les données des clients ont été modifiées et falsifiées par les pirates.", "L'interopérabilité, car la plateforme ne peut plus communiquer avec les banques."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-60", chapter: 5, difficulte: "difficile", question: "(Contexte) Lors d'une réunion, le directeur RH s'aperçoit que les commerciaux utilisent \"Google Drive\" pour partager des contrats confidentiels, car le logiciel de l'entreprise est trop lent.\nProblématique : Comment appelle-t-on ce phénomène et quel en est le risque ?", choix: ["Le Shadow IT, car l'usage de solutions non validées par la DSI expose l'entreprise à des failles de sécurité et des pertes de données (violation du RGPD).", "Le Shadow IT, car cela ralentit considérablement la bande passante internet de l'entreprise.", "Le Shadow IT, car cela permet aux salariés de demander des augmentations de salaires illégales.", "Le Crowdsourcing, car l'entreprise sous-traite gratuitement le stockage à Google."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-61", chapter: 5, difficulte: "difficile", question: "(Contexte) L'entreprise \"MenuiseriePlus\" a une rentabilité économique de 12%. Elle hésite entre financer sa nouvelle machine sur fonds propres ou souscrire un emprunt bancaire au taux d'intérêt de 4%.\nProblématique : Quelle décision d'endettement est financièrement la plus judicieuse ?", choix: ["Recourir à l'emprunt, car l'effet de levier financier est positif : la rentabilité de l'outil (12%) étant supérieure au coût de la dette (4%), l'endettement va doper la rentabilité des capitaux propres.", "Recourir à l'emprunt, car un taux de 4% se transforme mécaniquement en charges variables directes, ce qui augmente le seuil de rentabilité.", "Recourir à l'emprunt, car cela permet d'augmenter le capital social de l'entreprise sans faire appel aux actionnaires.", "Autofinancer à 100%, car tout endettement entraîne inévitablement un effet de massue destructeur de valeur."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-62", chapter: 5, difficulte: "difficile", question: "(Contexte) La société \"JouetBois\" constate que sa marge sur coût variable (MCV) annuelle est de 200 000 €. Or, ses charges fixes annuelles s'élèvent à 250 000 €.\nProblématique : Quel diagnostic financier peut-on établir ?", choix: ["L'entreprise est en perte, car sa marge sur coût variable est insuffisante pour couvrir la totalité de ses charges fixes : elle n'a pas atteint son seuil de rentabilité.", "L'entreprise est en perte, car sa Valeur Ajoutée est négative, les charges variables étant trop élevées.", "L'entreprise est en perte, car son Fonds de Roulement Net Global est absorbé par le BFR.", "L'entreprise est bénéficiaire, car une MCV positive garantit toujours un résultat courant avant impôt positif."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-63", chapter: 5, difficulte: "difficile", question: "(Contexte) Une entreprise de transport achète 10 nouveaux camions. Elle décide d'enregistrer la perte de valeur de ces véhicules (usure sur 5 ans) dans sa comptabilité de gestion.\nProblématique : Comment cette perte de valeur est-elle qualifiée et classée ?", choix: ["C'est une charge fixe (l'amortissement), car son montant annuel est calculé à l'avance et ne dépend pas du nombre de kilomètres parcourus ou du volume d'activité de l'année.", "C'est une charge fixe (l'amortissement), car elle correspond au remboursement mensuel strict du prêt bancaire ayant servi à acheter les camions.", "C'est une charge fixe (l'amortissement), car elle représente un décaissement immédiat de trésorerie qui annule le BFR.", "C'est une charge variable indirecte, car les camions s'usent plus vite s'ils roulent beaucoup."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-64", chapter: 5, difficulte: "difficile", question: "(Contexte) L'entreprise fabrique des chaussures. La ligne \"Bottes\" dégage un chiffre d'affaires de 100 000 € et des charges variables de 60 000 €. L'atelier exclusif de bottes coûte 50 000 € en loyer. L'entreprise supporte aussi 20 000 € de frais administratifs globaux.\nProblématique : Quelle décision prendre concernant la ligne \"Bottes\" en utilisant la méthode des coûts spécifiques ?", choix: ["Abandonner la ligne, car sa marge sur coûts spécifiques est négative (-10 000 €) : elle ne couvre même pas ses charges fixes directes et dégrade le résultat global de l'entreprise.", "Abandonner la ligne, car sa marge sur coût variable est insuffisante pour payer les frais administratifs globaux de 20 000 €.", "Abandonner la ligne, car son chiffre d'affaires est inférieur au montant total de toutes les charges de l'entreprise cumulées.", "Conserver la ligne, car la marge sur coût variable est positive (+40 000 €), ce qui assure la rentabilité économique."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-65", chapter: 5, difficulte: "difficile", question: "(Contexte) \"AgriMat\" a vendu pour 2 millions d'euros de tracteurs. Ses achats de pièces et d'énergie s'élèvent à 800 000 €. Elle a payé 500 000 € de salaires.\nProblématique : À combien s'élève sa Valeur Ajoutée et que représente-t-elle ?", choix: ["La Valeur Ajoutée est de 1 200 000 €, elle mesure la richesse brute créée par l'activité de production de l'entreprise avant la répartition entre les acteurs (salariés, État, etc.).", "La Valeur Ajoutée est de 1 200 000 €, elle représente l'excédent de trésorerie disponible à la fin du mois.", "La Valeur Ajoutée est de 1 200 000 €, elle correspond exactement au montant du Résultat Net Comptable distribuable aux actionnaires.", "La Valeur Ajoutée est de 700 000 €, car il faut retrancher les salaires pour connaître la vraie création de richesse de l'entreprise."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-66", chapter: 5, difficulte: "difficile", question: "(Contexte) Face à des difficultés, l'entreprise \"Moda\" (FRNG : 100 000 €, BFR : 140 000 €) décide de vendre un de ses entrepôts pour 60 000 € et d'encaisser l'argent.\nProblématique : Quel est l'impact mécanique sur l'équilibre du bilan fonctionnel ?", choix: ["Le FRNG augmente de 60 000 € (baisse d'un emploi stable), ce qui permet de couvrir le BFR et de restaurer une Trésorerie Nette positive (+20 000 €).", "Le FRNG augmente de 60 000 €, ce qui va creuser le BFR de manière proportionnelle car l'entreprise a moins de surface de stockage.", "Le FRNG augmente de 60 000 €, ce qui déclenche un effet de levier financier négatif (effet de massue) sur les capitaux propres.", "Le BFR diminue de 60 000 €, car la vente d'un entrepôt annule les dettes fournisseurs à court terme."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-67", chapter: 5, difficulte: "difficile", question: "(Contexte) La start-up \"LivraisonExpress\" connaît une croissance explosive. Cependant, ses clients (entreprises) paient à 60 jours, ce qui fait bondir ses créances clients de 200 000 €. Ses dettes fournisseurs augmentent de 50 000 €.\nProblématique : Quel est l'impact sur le cycle d'exploitation ?", choix: ["Une augmentation du BFR de 150 000 €, ce qui nécessite de trouver de nouvelles ressources financières stables (FRNG) pour éviter la cessation de paiement.", "Une augmentation du BFR de 150 000 €, ce qui améliore automatiquement l'Excédent Brut d'Exploitation (EBE).", "Une augmentation du BFR de 150 000 €, preuve que la marge sur coût spécifique de l'entreprise est excellente.", "Une diminution du BFR, car la hausse des créances clients constitue une rentrée de liquidités immédiate."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-68", chapter: 5, difficulte: "difficile", question: "(Contexte) L'entreprise \"Cuisines&Bains\" produit 500 cuisines par an. La crise immobilière fait chuter ses commandes à 300 cuisines. L'usine reste ouverte aux mêmes horaires.\nProblématique : Quelle est la conséquence en contrôle de gestion de cette sous-activité ?", choix: ["Une augmentation du coût fixe unitaire, car les charges fixes (loyer, assurances) restent stables mais se répartissent sur un moins grand nombre de cuisines, faisant grimper le coût de revient unitaire.", "Une augmentation du coût fixe unitaire, car l'entreprise doit licencier du personnel, ce qui génère des indemnités exceptionnelles.", "Une augmentation du coût fixe unitaire, car les fournisseurs de bois augmentent leurs prix pour compenser la baisse des volumes.", "Une baisse du coût variable unitaire, grâce aux économies d'échelle réalisées par l'arrêt de la production de 200 cuisines."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-69", chapter: 5, difficulte: "difficile", question: "(Contexte) \"Imprim'Express\" reçoit une commande de 10 000 flyers à 0,10 €/pièce. Le coût complet est de 0,15 € (dont 0,08 € de variable et 0,07 € de charges fixes). L'imprimerie tourne actuellement à 60% de sa capacité.\nProblématique : Doit-elle accepter cette commande et pourquoi ?", choix: ["Oui, car l'entreprise a des capacités inemployées : le prix (0,10 €) couvre le coût variable (0,08 €). La marge de 0,02 €/flyer viendra améliorer le résultat global, les charges fixes étant déjà payées par les autres clients.", "Oui, car le prix de vente permet de transformer la commande en une innovation de commercialisation de type Freemium.", "Oui, car l'entreprise doit obligatoirement vendre en dessous du coût complet pour respecter le principe de l'économie de la fonctionnalité.", "Non, car une vente à 0,10 € engendre une perte comptable stricte de 0,05 € par flyer, conduisant à la faillite à court terme."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-70", chapter: 6, difficulte: "difficile", question: "(Contexte) L'Assemblée Générale des actionnaires décide de ne distribuer aucun dividende cette année et de mettre l'intégralité du Résultat Net en réserves.\nProblématique : Quel est l'impact de cette décision de répartition sur le bilan ?", choix: ["Un renforcement des ressources stables (capitaux propres), ce qui augmente le FRNG et favorise la capacité d'autofinancement des futurs investissements.", "Un renforcement des ressources stables, ce qui déclenche mécaniquement une baisse du BFR d'exploitation.", "Un renforcement des ressources stables, ce qui oblige l'entreprise à souscrire un emprunt pour compenser le manque à gagner des actionnaires.", "Une dégradation de la Trésorerie Nette, car la non-distribution des dividendes est lourdement taxée par l'État."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-71", chapter: 6, difficulte: "difficile", question: "(Contexte) Le PDG de \"Cosmetica\" prend la décision d'acheter son principal concurrent américain pour s'implanter aux États-Unis.\nProblématique : Comment qualifier cette décision selon Mintzberg ?", choix: ["C'est une décision stratégique, car elle engage l'avenir de l'organisation sur le long terme, nécessite des ressources massives et est difficilement réversible.", "C'est une décision stratégique, car elle modifie l'organisation du travail quotidien des ouvriers français (enrichissement des tâches).", "C'est une décision stratégique, car elle nécessite le déploiement d'une technologie Blockchain pour être valide.", "C'est une décision opérationnelle, car elle relève de la routine habituelle d'un grand groupe multinational."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-72", chapter: 6, difficulte: "difficile", question: "(Contexte) Pour lutter contre l'absentéisme de ses caissières, un supermarché remplace les primes de présence par la rotation des postes (caisse, rayon, accueil) pour lutter contre la monotonie.\nProblématique : Quelle théorie de la motivation justifie ce choix managérial ?", choix: ["La théorie de Herzberg, car le supermarché agit sur les \"facteurs moteurs\" (intérêt et contenu du travail) plutôt que sur les seuls \"facteurs d'hygiène\" (rémunération) pour générer une motivation intrinsèque.", "La théorie de Herzberg, car elle postule que l'homme est naturellement fainéant (Théorie X) et doit être contraint par des tâches plus dures.", "La théorie de Herzberg, car elle impose la supervision directe comme seul moyen de coordination efficace.", "La pyramide de Maslow, car la rotation des postes répond au besoin physiologique de survie."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-73", chapter: 6, difficulte: "difficile", question: "(Contexte) Les entreprises technologiques \"Uber\" et \"Deliveroo\" fondent leur activité sur des chauffeurs ou coursiers auto-entrepreneurs.\nProblématique : Quel défi juridique ce modèle de plateforme soulève-t-il régulièrement devant les tribunaux ?", choix: ["La requalification en contrat de travail salarié si un lien de subordination juridique (contrôle, sanctions) est prouvé par les juges, remettant en cause le modèle économique de \"l'ubérisation\".", "La requalification en contrat de travail salarié, car la loi interdit formellement de sous-traiter la livraison à des particuliers sans certification Blockchain.", "La requalification en contrat de travail salarié, car l'Open Data oblige les plateformes à publier les salaires horaires.", "La violation de la standardisation des qualifications, car les chauffeurs n'ont pas de diplôme de transport."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-74", chapter: 6, difficulte: "difficile", question: "(Contexte) Une marque de vêtements crée un modèle économique où le client achète un abonnement mensuel donnant droit à recevoir 3 vêtements \"surprises\" chaque mois.\nProblématique : Quelle est cette stratégie d'innovation ?", choix: ["Une innovation de modèle économique, car la marque génère des revenus récurrents (abonnement) modifiant la logique traditionnelle de vente à la pièce.", "Une innovation de modèle économique, car elle implique la relocalisation de la production (innovation de procédé).", "Une innovation de modèle économique, car la marque vend le service d'usage du vêtement (économie de la fonctionnalité).", "Une innovation de produit, car les vêtements sont \"surprises\", ce qui en fait des biens intangibles."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-75", chapter: 6, difficulte: "difficile", question: "(Contexte) Le ministère de la Justice met en place une interface (API) permettant au logiciel de la police nationale de consulter automatiquement les casiers judiciaires sans que les agents n'aient à ressaisir d'informations.\nProblématique : Quel avantage informatique (SI) cela démontre-t-il ?", choix: ["L'interopérabilité des systèmes, qui permet à des bases de données indépendantes de communiquer et d'échanger de l'information de manière fluide et sécurisée.", "L'interopérabilité des systèmes, qui crypte les données grâce à la méthode du Pair-à-Pair.", "L'interopérabilité des systèmes, qui garantit au citoyen le droit à la déconnexion numérique.", "La transparence des algorithmes imposée par le Règlement Général sur la Protection des Données."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-76", chapter: 6, difficulte: "difficile", question: "(Contexte) Lors d'une grève contre l'allongement du temps de travail, les représentants syndicaux demandent à consulter le Bilan Social de l'entreprise (effectifs + de 300).\nProblématique : Que vont-ils y trouver pour nourrir le dialogue social ?", choix: ["Les indicateurs quantitatifs (turn-over, masse salariale, nombre d'accidents, heures de formation) permettant d'analyser objectivement la politique RH et les conditions de travail des trois dernières années.", "Les indicateurs quantitatifs (chiffre d'affaires, FRNG, BFR) permettant de justifier une augmentation des dividendes aux actionnaires.", "Les indicateurs quantitatifs (marge sur coût spécifique, seuil de rentabilité) de chaque ligne de produit.", "Le code source de l'algorithme de calcul des primes de productivité."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-77", chapter: 6, difficulte: "difficile", question: "(Contexte) L'entreprise \"AirFrance\" a un taux d'endettement très élevé. Son directeur financier craint une \"cessation de paiement\" imminente suite à la hausse du prix du kérosène.\nProblématique : Quel indicateur reflète précisément l'incapacité à payer ses dettes à court terme ?", choix: ["Une Trésorerie Nette durablement négative, indiquant que le FRNG ne suffit plus à couvrir le BFR, et que les banques refusent de nouveaux découverts.", "Une Trésorerie Nette durablement négative, indiquant que l'Excédent Brut d'Exploitation est artificiellement gonflé par le Greenwashing.", "Une Trésorerie Nette durablement négative, causée par l'allongement du délai de paiement des fournisseurs.", "Une rentabilité économique négative, preuve que les capitaux propres sont inférieurs aux dettes financières."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-78", chapter: 6, difficulte: "difficile", question: "(Contexte) La start-up \"FairPhone\" conçoit son smartphone pour qu'il soit facilement démontable, réparable, et utilise des minéraux issus du commerce équitable.\nProblématique : Dans quelle approche RSE cette conception s'inscrit-elle ?", choix: ["L'éco-conception au sein de l'économie circulaire, visant à allonger le cycle de vie du produit (PLM) et à minimiser l'épuisement des ressources naturelles.", "L'éco-conception au sein de l'économie circulaire, permettant d'accélérer l'obsolescence programmée pour générer des revenus d'abonnement.", "L'éco-conception au sein de l'économie circulaire, justifiant l'application d'un modèle Freemium matériel.", "La démocratie participative, le client assemblant lui-même son téléphone."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-79", chapter: 6, difficulte: "difficile", question: "(Contexte) La direction de \"Decathlon\" laisse chaque chef de rayon commander les produits qu'il juge adaptés à la météo de sa région, sans demander l'autorisation au siège parisien.\nProblématique : Comment s'appelle ce mode d'organisation du pouvoir ?", choix: ["La décentralisation du pouvoir (principe de subsidiarité), car la décision est prise par l'échelon hiérarchique le plus proche du terrain, favorisant l'agilité et la réactivité de l'entreprise.", "La décentralisation du pouvoir, car le siège parisien impose des normes de standardisation des procédés extrêmement rigides.", "La décentralisation du pouvoir, car elle permet d'externaliser le risque financier vers des travailleurs indépendants.", "L'ajustement mutuel, car le chef de rayon discute avec le client avant de fixer le prix de l'article."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-80", chapter: 6, difficulte: "difficile", question: "(Contexte) Lors du scandale des \"Panama Papers\", une salariée d'un cabinet d'avocats a fuité des documents confidentiels prouvant l'évasion fiscale massive de grandes entreprises. Elle a été poursuivie en justice.\nProblématique : En éthique des affaires, comment justifier juridiquement sa protection ?", choix: ["Par son statut de lanceur d'alerte, qui protège pénalement la personne signalant de bonne foi, dans l'intérêt général, un crime ou un délit grave commis par son organisation.", "Par son statut de lanceur d'alerte, qui autorise tout salarié à monnayer des secrets industriels (Shadow IT) auprès de la presse en échange d'une prime de résultat.", "Par son statut de lanceur d'alerte, car l'Open Data oblige les cabinets d'avocats à publier l'intégralité de la comptabilité de leurs clients en ligne.", "Par la théorie des parties prenantes, qui lui confère l'immunité syndicale absolue."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-81", chapter: 6, difficulte: "difficile", question: "(Contexte) Dans une concession Renault, tous les mécaniciens appliquent scrupuleusement la fiche de procédure numéro 42 pour réaliser la vidange d'un véhicule hybride.\nProblématique : Quel mécanisme de coordination de Mintzberg garantit la qualité ici ?", choix: ["La standardisation des procédés de travail, car le contenu de la tâche et les étapes d'exécution sont spécifiés à l'avance de manière stricte pour assurer l'uniformité du service.", "La standardisation des procédés de travail, car la direction contrôle visuellement (supervision directe) le temps passé sur chaque véhicule.", "La standardisation des procédés de travail, car les mécaniciens négocient ensemble la meilleure façon de réparer le moteur (ajustement mutuel).", "La standardisation des qualifications, chaque mécanicien inventant sa propre méthode grâce à son diplôme de haut niveau."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-82", chapter: 6, difficulte: "difficile", question: "(Contexte) Face à des difficultés économiques, l'entreprise \"Moda\" supprime tous ses entrepôts régionaux et vend désormais ses vêtements exclusivement depuis son usine centrale via son site internet.\nProblématique : Quelle est la conséquence logistique et commerciale (Supply Chain) de ce choix ?", choix: ["La désintermédiation par la mise en place d'un circuit de distribution ultra-court (canal direct), permettant à la marque de capter l'intégralité de la marge commerciale.", "La désintermédiation par la mise en place d'un circuit de distribution ultra-court, augmentant massivement les charges fixes liées aux entrepôts supprimés.", "La désintermédiation par la mise en place d'un circuit de distribution ultra-court, ce qui dégrade automatiquement la Valeur Ajoutée produite.", "La création d'un écosystème territorial d'innovation (cluster) autour de l'usine centrale."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-83", chapter: 6, difficulte: "difficile", question: "(Contexte) Pour répondre aux accusations de discrimination à l'embauche, le cabinet \"RecrutPro\" supprime la photo, l'âge et l'adresse des CV. Les candidats passent d'abord des tests techniques sur ordinateur.\nProblématique : Quelle est la finalité managériale et sociétale de cette pratique RH ?", choix: ["Garantir l'égalité des chances, l'éthique de sélection et la diversité en se concentrant sur l'évaluation objective des compétences, limitant ainsi les biais cognitifs du recruteur.", "Garantir l'égalité des chances, afin de contourner l'obligation légale d'embaucher des travailleurs en situation de handicap (social washing).", "Garantir l'égalité des chances, en appliquant le principe d'interopérabilité des bases de données RH prévu par le RGPD.", "Favoriser le mécanisme d'ajustement mutuel lors des entretiens de recrutement."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-84", chapter: 6, difficulte: "difficile", question: "(Contexte) Une grande surface réduit ses coûts en employant massivement des étudiants à temps partiel et des intérimaires, qui changent chaque mois.\nProblématique : Quel est le coût caché de cette stratégie de flexibilité quantitative extrême ?", choix: ["Une forte hausse des dépenses en recrutement, en formation initiale et une perte globale de la qualité de service (erreur de caisse, méconnaissance des produits) due à l'absence de fidélisation.", "Une forte hausse des dépenses en recrutement, car les étudiants exigent des rémunérations supérieures au SMIC grâce au principe de démocratie participative.", "Une forte hausse des dépenses en recrutement, augmentant mécaniquement la rentabilité économique des capitaux propres de l'enseigne.", "La baisse immédiate du taux de rotation du personnel (turn-over) du magasin."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-85", chapter: 6, difficulte: "difficile", question: "(Contexte) \"Le Slip Français\" communique fortement sur le \"Made in France\", mais une enquête révèle que certains emballages proviennent d'usines non conformes en Asie. La marque publie immédiatement une vidéo d'excuses de son dirigeant et annonce le changement de fournisseur.\nProblématique : Quelle stratégie de communication l'entreprise déploie-t-elle ?", choix: ["Une communication de crise, visant à limiter l'impact du bad buzz sur son e-réputation, restaurer la confiance et protéger son capital de marque.", "Une communication de crise, car la loi lui interdit d'utiliser des campagnes de \"Paid Media\" en période de controverse écologique.", "Une communication de crise, visant à modifier le business plan prévisionnel auprès de ses partenaires financiers institutionnels.", "Une démarche classique d'Open Data pour partager ses algorithmes logistiques avec ses concurrents."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-86", chapter: 6, difficulte: "difficile", question: "(Contexte) La compagnie aérienne \"LowFly\" pratique des prix cassés en ne proposant aucun repas à bord, aucun bagage en soute, et en facturant l'impression de la carte d'embarquement à l'aéroport.\nProblématique : Quel modèle économique permet à l'entreprise d'être rentable avec des prix si bas ?", choix: ["Le modèle \"Low Cost\", car l'entreprise élimine tous les services non essentiels pour rationaliser drastiquement ses charges fixes et variables, se rattrapant sur le volume des ventes (rotation élevée).", "Le modèle \"Low Cost\", car l'entreprise pratique une vente à perte (dumping) systématique financée par des subventions croisées d'État.", "Le modèle \"Low Cost\", car l'entreprise s'appuie sur la stratégie Freemium où seuls les passagers \"Premium\" ont le droit de voyager.", "L'économie de la fonctionnalité, car la compagnie vend des avions plutôt que des trajets."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-87", chapter: 6, difficulte: "difficile", question: "(Contexte) Un salarié du pôle R&D de chez \"Samsung\" télécharge sur sa clé USB personnelle les plans secrets du prochain smartphone pour travailler depuis chez lui (sans que la DSI ne le sache). Il perd sa clé dans le métro.\nProblématique : Quel concept illustre la cause de cette fuite de données stratégiques ?", choix: ["Le \"Shadow IT\", car le contournement des outils officiels sécurisés du SI par des employés bien intentionnés expose l'organisation à la compromission de son patrimoine informationnel.", "Le \"Shadow IT\", car le salarié a agi en tant que lanceur d'alerte pour dénoncer une fraude technologique.", "Le \"Shadow IT\", car la perte de la clé USB relève de l'obsolescence programmée imposée par le constructeur.", "Le principe d'Open Data, car les plans d'un smartphone relèvent de la démocratie participative ouverte au public."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-88", chapter: 6, difficulte: "difficile", question: "(Contexte) Une entreprise de bâtiment calcule son seuil de rentabilité. Ses charges fixes s'élèvent à 500 000 €. Son chiffre d'affaires est de 2 000 000 € et ses charges variables de 1 200 000 €.\nProblématique : Comment calcule-t-on la Marge sur Coûts Variables (MCV) pour savoir si elle couvre les charges fixes ?", choix: ["La MCV est de 800 000 € (CA - Charges variables). Elle est supérieure aux charges fixes (500 000 €), donc l'entreprise a dépassé son seuil de rentabilité et dégage un bénéfice opérationnel.", "La MCV est de 800 000 € (CA - Charges variables). Elle est supérieure aux charges fixes, ce qui signifie que l'entreprise doit obligatoirement abandonner ce marché devenu trop risqué.", "La MCV est de - 300 000 € (Charges fixes - Charges variables), l'entreprise est donc en perte et doit contracter un emprunt de trésorerie passive.", "La MCV est égale au FRNG (1 200 000 €), l'entreprise peut donc investir massivement en R&D."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-89", chapter: 6, difficulte: "difficile", question: "(Contexte) Les fondateurs de l'entreprise d'horlogerie \"Lip\" ont transmis à leurs successeurs un esprit \"combatif et d'innovation sociale\", souvent rappelé lors des séminaires d'intégration des nouveaux salariés.\nProblématique : Quel élément clé du management cela représente-t-il ?", choix: ["La culture d'organisation (via ses mythes fondateurs et rites), qui sert de ciment interne pour fédérer les équipes autour d'une identité commune, favorisant la cohésion et l'implication au travail.", "La culture d'organisation, car elle permet de standardiser strictement les qualifications techniques des horlogers recrutés.", "La culture d'organisation, qui a pour unique but de rédiger le plan de développement des compétences exigé par l'inspection du travail.", "Le système d'information de gestion de l'entreprise, formalisant le mécanisme de la supervision directe."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-90", chapter: 6, difficulte: "difficile", question: "(Contexte) Dans une concession, un vendeur automobile voit qu'une voiture est en stock sur son ordinateur. Or, le chef d'atelier vient de commander des pièces pour la réparer suite à une grêle, sans que le système du vendeur ne l'indique. Le vendeur vend donc une voiture accidentée.\nProblématique : Quelle carence du Système d'Information ce dysfonctionnement met-il en évidence ?", choix: ["Le manque d'intégration des données (effet silo) : l'absence d'un PGI (Progiciel de Gestion Intégré) centralisé empêche la mise à jour en temps réel de l'information pour tous les métiers (unicité de la donnée).", "Le manque d'intégration des données, car la technologie de la Blockchain a volontairement crypté l'état du véhicule pour respecter le RGPD.", "Le manque d'intégration des données, car le vendeur n'a pas utilisé le Cloud Computing pour effectuer sa vente en télétravail.", "La sous-activité chronique de l'atelier de réparation, générant une marge sur coût spécifique négative."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-91", chapter: 6, difficulte: "difficile", question: "(Contexte) Pour attirer de nouveaux clients professionnels, la banque \"BTP Finance\" met en place une API permettant au logiciel comptable des artisans de se connecter directement à leur compte bancaire pour automatiser la trésorerie.\nProblématique : Quel avantage numérique la banque offre-t-elle ici ?", choix: ["L'interopérabilité des systèmes, créant de la valeur pour le client en supprimant les saisies manuelles redondantes entre deux bases de données distinctes (banque et PME).", "L'interopérabilité des systèmes, car elle oblige l'artisan à adopter une structure divisionnelle pour gérer ses flux poussés.", "L'interopérabilité des systèmes, garantissant à la banque la propriété intellectuelle exclusive des factures du client (Open Data).", "L'ajustement mutuel, car le conseiller bancaire appellera l'artisan chaque matin."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-92", chapter: 6, difficulte: "difficile", question: "(Contexte) La société \"Uber\" a été condamnée dans plusieurs pays européens, les juges estimant que les chauffeurs n'étaient pas de vrais indépendants, car l'application leur imposait les tarifs, gérait les itinéraires et pouvait les désactiver (\"déconnecter\") arbitrairement.\nProblématique : Sur quel critère juridique la requalification en contrat de travail repose-t-elle ?", choix: ["Le \"lien de subordination\", car l'existence de directives, de contrôle et d'un pouvoir de sanction par l'algorithme caractérise le salariat, remettant en cause le modèle économique de \"l'ubérisation\".", "Le \"lien de subordination\", car les chauffeurs Uber bénéficient d'un style de direction consultatif (Likert) empêchant l'application de la théorie des parties prenantes.", "Le \"lien de subordination\", car les chauffeurs utilisaient la Blockchain pour fixer les prix des courses de manière décentralisée.", "La supervision directe, car l'algorithme est reconnu comme une innovation de produit immatériel."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-93", chapter: 6, difficulte: "difficile", question: "(Contexte) Le fournisseur \"FourniTech\" exige que la start-up \"InnovApps\" règle ses achats de composants informatiques comptant (0 jour de délai). Les clients d'\"InnovApps\" (les mairies) la paient à 90 jours.\nProblématique : Quel est l'impact désastreux sur la pérennité financière de la start-up ?", choix: ["L'explosion de son Besoin en Fonds de Roulement (BFR), créant un trou de trésorerie (besoin de financement massif) qui, s'il n'est pas couvert par un solide FRNG ou un emprunt à court terme, mènera à la cessation de paiements.", "L'explosion de son BFR, car le paiement au comptant des fournisseurs génère des dividendes artificiels taxés par l'administration fiscale.", "L'explosion de son BFR, ce qui augmentera automatiquement la Marge sur Coûts Variables de ses applications vendues.", "L'annulation de la Valeur Ajoutée (VA), car le crédit inter-entreprises est illégal entre une start-up et une administration publique."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-94", chapter: 6, difficulte: "difficile", question: "(Contexte) Le directeur d'un groupe industriel affirme : \"Nous gérons les employés comme les machines. Ils doivent exécuter leur tâche précisément, sans réfléchir, pour maximiser la cadence et minimiser les coûts unitaires.\"\nProblématique : À quelle théorie fondamentale du management cette déclaration fait-elle écho ?", choix: ["L'Organisation Scientifique du Travail (OST / Taylorisme), caractérisée par la parcellisation des tâches, la stricte séparation entre conception et exécution, et la standardisation des procédés.", "L'Organisation Scientifique du Travail (OST), car elle repose sur la Théorie Y (McGregor) postulant que l'individu cherche naturellement à prendre des responsabilités dans son emploi.", "L'Organisation Scientifique du Travail (OST), car elle privilégie l'enrichissement des tâches pour lutter contre l'absentéisme et les risques psychosociaux (RPS).", "Le Lean Management, car le directeur cherche à éliminer le gaspillage lié au dialogue social."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-95", chapter: 6, difficulte: "difficile", question: "(Contexte) \"BlaBlaCar\" et \"Vinted\" ne fabriquent rien. Elles se contentent de mettre en relation un grand nombre d'offreurs et de demandeurs. La valeur de la plateforme augmente à mesure que de nouveaux utilisateurs s'inscrivent.\nProblématique : Comment appelle-t-on la force qui consolide ce modèle de plateforme ?", choix: ["L'effet de réseau (ou externalité de réseau), car l'utilité du service (et donc sa puissance concurrentielle) croît exponentiellement avec le nombre de participants actifs sur la plateforme.", "L'effet de réseau, car l'entreprise pratique une intégration verticale complète pour s'assurer que les utilisateurs ne partent pas chez un concurrent.", "L'effet de réseau, car la Blockchain garantit l'anonymat absolu des acheteurs et des vendeurs.", "La standardisation des qualifications, car les chauffeurs et les vendeurs doivent posséder le même diplôme."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-96", chapter: 6, difficulte: "difficile", question: "(Contexte) Une entreprise de BTP décide d'inclure dans les critères d'évaluation annuelle de ses cadres dirigeants, en plus de l'EBE, le nombre d'accidents du travail survenus sur leurs chantiers et le pourcentage de déchets recyclés.\nProblématique : Quelle évolution du pilotage de la performance cela illustre-t-il ?", choix: ["Le passage d'une vision purement financière à l'évaluation de la \"Performance Globale\", intégrant des indicateurs de RSE (sociaux et environnementaux) dans la stratégie et la gouvernance.", "Le passage à la \"Performance Globale\", car cela permet légalement de baisser les salaires fixes des cadres en cas d'accident sur un chantier.", "Le passage à la \"Performance Globale\", car le recyclage des déchets est une obligation de la norme comptable du calcul du Fonds de Roulement Net Global.", "L'abandon du Bilan Social, puisque ces données seront désormais intégrées dans le compte de résultat de l'entreprise."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-97", chapter: 6, difficulte: "difficile", question: "(Contexte) Une petite entreprise familiale de confiserie connaît le succès. Le patriarche, très autoritaire, décide de nommer son fils à la direction du marketing, bien qu'il n'ait aucune compétence, refusant de recruter un cadre externe.\nProblématique : En théorie des organisations (croissance), à quelle crise typique cette PME s'expose-t-elle ?", choix: ["La crise de direction/leadership (Greiner), l'organisation ayant grandi au-delà de la capacité d'un dirigeant centralisateur à tout gérer de manière paternaliste, nécessitant une délégation (décentralisation) du pouvoir et des compétences managériales formelles.", "La crise de direction, car l'entreprise a subi un effet de massue financier lié au versement abusif des dividendes familiaux.", "La crise de direction, car la standardisation des procédés de fabrication des bonbons a rendu le travail du fils totalement obsolète.", "Le conflit d'agence (Théorie de l'Agence), car les intérêts du patriarche (actionnaire) s'opposent radicalement aux intérêts de son fils (dirigeant)."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-98", chapter: 6, difficulte: "difficile", question: "(Contexte) Le constructeur \"Dyson\" investit des millions dans la conception de ses aspirateurs cycloniques. Il les vend au prix très élevé de 800 €, misant sur le design, l'image technologique de la marque et l'absence de perte d'aspiration.\nProblématique : Sur quel avantage concurrentiel sa stratégie marketing (Mix) s'appuie-t-elle ?", choix: ["Une stratégie de différenciation par le haut (sophistication), justifiant un prix d'écrémage grâce à la valeur perçue (innovation, capital marque) très supérieure à l'offre standard.", "Une stratégie de différenciation par le haut, car l'entreprise vise une domination globale par les coûts en saturant les capacités de ses usines asiatiques.", "Une stratégie de différenciation par le haut, imposant une innovation de procédé où les clients assemblent eux-mêmes leur aspirateur (économie collaborative).", "Une stratégie de prix de pénétration, car 800 € représente le seuil de rentabilité strict de l'innovation de rupture."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-99", chapter: 6, difficulte: "difficile", question: "(Contexte) Une entreprise technologique souhaite lever des fonds mais ne veut pas que de nouveaux actionnaires (Venture Capital / Fonds d'investissement) puissent dicter la stratégie en Conseil d'Administration.\nProblématique : Quel arbitrage de financement le directeur financier doit-il choisir ?", choix: ["L'endettement par emprunt bancaire ou obligataire, car bien qu'il dégrade l'indépendance financière, il ne dilue pas le capital (pas de perte de contrôle du pouvoir décisionnel).", "L'endettement par emprunt bancaire, car il permet d'augmenter les capitaux propres de l'entreprise et de réduire mécaniquement les charges d'intérêts d'exploitation.", "L'endettement par emprunt bancaire, car les banques acceptent toujours le mécanisme du crédit-bail pour les besoins liés à la trésorerie passive de l'entreprise.", "L'augmentation de capital, car les nouveaux actionnaires (Business Angels) apportent uniquement de la trésorerie sans exiger de droit de vote aux assemblées."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-100", chapter: 6, difficulte: "difficile", question: "(Contexte) \"Le Slip Français\" relocalise toute sa fabrication en France, paie des salaires élevés, utilise du coton recyclé et promeut des campagnes d'inclusion. Ses coûts sont élevés, mais sa clientèle, engagée, est prête à payer plus cher.\nProblématique : En guise de conclusion transversale sur le management contemporain, que démontre ce cas d'école ?", choix: ["L'alignement stratégique : la cohérence forte entre ses valeurs éthiques (RSE), son modèle de production (relocalisation/innovation de procédé) et son positionnement marketing (différenciation/marque) génère un modèle d'affaires performant et créateur de valeur globale.", "L'alignement stratégique, prouvant que le \"Social Washing\" est la seule technique de communication permettant de justifier une marge sur coût spécifique négative à long terme.", "L'alignement stratégique, confirmant la théorie taylorienne selon laquelle seule la supervision directe stricte des ouvriers français permet de dégager un Excédent Brut d'Exploitation (EBE) positif.", "L'alignement stratégique, car l'entreprise respecte le principe d'Open Data en publiant les salaires de ses dirigeants sur la Blockchain."] as [string, string, string, string], bonIndex: 0 },
];
